package main

import "github.com/egoist/mygo/ui"

// The icons the window draws, as 24×24 stroke SVGs in the Lucide style: they
// take the color of the text and scale with FontSize. MyGo Music draws its own
// at 1.75 points; the launcher follows.
func svg(d string) *ui.SVG {
	return ui.MustParseSVG([]byte(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">` + d + `</svg>`))
}

